263	function validateResponse(raw: string, segment: Segment): {
264	  summary: string;
265	  pointsToConsider: Explanation["pointsToConsider"];
266	  concepts: Concept[];
267	} {
268	  let obj: RawExplanation;
269	  try {
270	    obj = JSON.parse(raw);
271	  } catch {
272	    throw new ValidationFailure("response is not valid JSON");
273	  }
274	
275	  if (typeof obj.summary !== "string" || obj.summary.length < MIN_SUMMARY_LEN) {
276	    throw new ValidationFailure(`summary is missing or shorter than ${MIN_SUMMARY_LEN} chars`);
277	  }
278	  if (obj.summary.trim().toLowerCase() === segment.oneLiner.trim().toLowerCase()) {
279	    throw new ValidationFailure("summary is identical to segment.oneLiner — agent must expand on the one-liner, not echo it");
280	  }
281	
282	  const ptcIn = obj.pointsToConsider ?? {};
283	  const pointsToConsider = {
284	    assumptions: filterPtcItems(ptcIn.assumptions),
285	    dangers: filterPtcItems(ptcIn.dangers),
286	    sideEffects: filterPtcItems(ptcIn.sideEffects),
287	  };
288	
289	  const conceptsRaw = Array.isArray(obj.concepts) ? obj.concepts : [];
290	  const concepts: Concept[] = [];
291	  const seen = new Set<string>();
292	  for (const c of conceptsRaw) {
293	    if (!c || typeof (c as any).name !== "string" || (c as any).name.length === 0) continue;
294	    if (typeof (c as any).briefExplainer !== "string" || (c as any).briefExplainer.length === 0) continue;
295	    if (typeof (c as any).relevance !== "string" || (c as any).relevance.length === 0) continue;
296	    const key = (c as any).name.trim().toLowerCase();
297	    if (seen.has(key)) continue;
298	    seen.add(key);
299	    concepts.push({
300	      name: (c as any).name,
301	      briefExplainer: (c as any).briefExplainer,
302	      relevance: (c as any).relevance,
303	    });
304	  }
305	
306	  return { summary: obj.summary, pointsToConsider, concepts };
307	}
308	
309	function filterPtcItems(x: unknown): string[] {
310	  if (!Array.isArray(x)) return [];
311	  return x.filter(
312	    (s): s is string =>
313	      typeof s === "string"
314	      && s.length >= MIN_PTC_ITEM_LEN
315	      && !GENERIC_PTC_RE.test(s.trim()),
316	  );
317	}
