  const seen = new Set<string>();
  for (const c of conceptsRaw) {
    if (!c || typeof (c as any).name !== "string" || (c as any).name.length === 0) continue;
    if (typeof (c as any).briefExplainer !== "string" || (c as any).briefExplainer.length === 0) continue;
