      let partialCount = 0;
      let firstChunkMs: number | undefined;
      let firstPartialMs: number | undefined;
      try {
        const stream = deps.adapter.completeStream(messages, {
          responseFormat: useJsonSchema ? "json_object" : "json_object",
          signal: ac.signal,
