async function* streamWithIdleTimeout(
  iter: AsyncIterable<string>,
  idleTimeoutMs: number,
  _signal: AbortSignal,
): AsyncGenerator<string> {
  const iterator = iter[Symbol.asyncIterator]();
  while (true) {
