}

class CodeWalkComment implements vscode.Comment {
  constructor(
    public body: vscode.MarkdownString,
    public mode: vscode.CommentMode = vscode.CommentMode.Preview,
    public author: vscode.CommentAuthorInformation = { name: "CodeWalk" },
