private onExplanationChanged(segmentId: string): void {
  if (!this.openThread || this.openSegment?.id !== segmentId) return;
  const exp = this.expStore.get(segmentId, this.deps.preset, this.deps.promptVersion);
  if (!exp) return;
  if (exp.renderState === "done" && !this.loaderTimer) {
    // Done-state arrived while no typewriter was running (direct cache population).
    // Render immediately; there's nothing to animate.
    this.openThread.comments = [new CodeWalkComment(renderExplanation(exp))];
  } else if (this.loaderTimer) {
    // Partial arrived mid-stream — snap the typewriter to the latest summary immediately
    // so display tracks streaming without waiting up to TYPEWRITER_INTERVAL_MS for the next
    // tick. When renderState flips to done, the typewriter keeps ticking until it catches
    // up, then the tick itself swaps in the full rendered explanation.
    this.renderLoaderFrame();
  }
}

