    this.openTokenSource = new vscode.CancellationTokenSource();
    const fileContext = ""; // Future work: full-file context. Phase 2 leaves this empty.
    this.startLoader();
    this.expStore.set(segmentId, this.deps.preset, this.deps.promptVersion, {
