// Typewriter tunables. 30Hz is perceptually smooth for typing but keeps us under VS Code's
// CommentThread update throughput — 60Hz caused the renderer to starve updates and never
// commit a frame during streaming.
const TYPEWRITER_INTERVAL_MS = 33;
const TYPEWRITER_CATCHUP_FRAMES = 30;
