private startLoader(): void {
  if (this.loaderTimer) return;
  this.loaderStartMs = Date.now();
  this.displayedLength = 0;
  this.lastRenderedBody = undefined;
  this.renderLoaderFrame();
  this.loaderTimer = setInterval(() => this.renderLoaderFrame(), TYPEWRITER_INTERVAL_MS);
}

private renderLoaderFrame(): void {
  if (!this.openThread || !this.openSegment || this.loaderStartMs === undefined) return;
  const exp = this.expStore.get(this.openSegment.id, this.deps.preset, this.deps.promptVersion);
  if (!exp) return;
  const received = exp.summary;

  // Advance typewriter: cap catch-up so a single-shot burst (Groq) still animates.
  const backlog = received.length - this.displayedLength;
  if (backlog > 0) {
    const byCatchup = Math.ceil(backlog / TYPEWRITER_CATCHUP_FRAMES);
    const charsPerFrame = Math.min(TYPEWRITER_MAX_CHARS_PER_FRAME, Math.max(1, byCatchup));
    this.displayedLength = Math.min(received.length, this.displayedLength + charsPerFrame);
  }

  // If producer finished AND typewriter caught up, swap to the final rendered form.
  if (exp.renderState === "done" && this.displayedLength >= received.length) {
    this.stopLoader();
    this.openThread.comments = [new CodeWalkComment(renderExplanation(exp))];
    return;
  }

  const visibleSummary = received.slice(0, this.displayedLength);
  const elapsedMs = Date.now() - this.loaderStartMs;
  const dotCount = 1 + Math.floor(elapsedMs / 400) % 3;
  const dots = ".".repeat(dotCount);
  const secs = (elapsedMs / 1000).toFixed(1);
  const body = visibleSummary.length === 0
    ? `_Analyzing${dots} (${secs}s)_`
    : `${visibleSummary}\n\n---\n\n_Gathering details${dots} (${secs}s)_`;
  if (body === this.lastRenderedBody) return;
  this.lastRenderedBody = body;
  const md = new vscode.MarkdownString(body, true);
  md.supportHtml = true;
  md.isTrusted = false;
  this.openThread.comments = [new CodeWalkComment(md)];
}

private stopLoader(): void {
  if (this.loaderTimer) {
    clearInterval(this.loaderTimer);
    this.loaderTimer = undefined;
    this.loaderStartMs = undefined;
    this.displayedLength = 0;
    this.lastRenderedBody = undefined;
  }
}

